package com.raiiiden.warborn.common.item;import net.minecraft.world.item.ItemStack;public class WBArmorItem{public static void setInsertedGoggles(ItemStack h,ItemStack g){h.components.put("goggles",g);}public static void setInsertedBattery(ItemStack h,ItemStack b){h.components.put("battery",b);}public static ItemStack getInsertedGoggles(ItemStack h){return (ItemStack)h.components.getOrDefault("goggles",ItemStack.EMPTY);}public static ItemStack getInsertedBattery(ItemStack h){return (ItemStack)h.components.getOrDefault("battery",ItemStack.EMPTY);}}
